// Bundles the image worker (src/still-worker.ts) into one script and writes
// it as a string module, src/still-worker.gen.ts. The package starts the
// worker from that string through a blob URL, so apps need no worker file
// or bundler setup. The generated file is not committed.
import { mkdtemp, readFile, rm, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { fileURLToPath } from "node:url";
import { build } from "tsup";

const root = fileURLToPath(new URL("..", import.meta.url));
const out = await mkdtemp(join(tmpdir(), "avatar-worker-"));
try {
  await build({
    entry: { worker: join(root, "src/still-worker.ts") },
    format: ["iife"],
    platform: "browser",
    target: "es2020",
    outDir: out,
    minify: true,
    dts: false,
    sourcemap: false,
    clean: false,
    silent: true,
    config: false,
  });
  const code = await readFile(join(out, "worker.global.js"), "utf8");
  await writeFile(
    join(root, "src/still-worker.gen.ts"),
    `// Generated by scripts/build-worker.mjs from src/still-worker.ts. Do not edit.\nconst source: string = ${JSON.stringify(code)};\nexport default source;\n`,
  );
} finally {
  await rm(out, { recursive: true, force: true });
}
